INSERT INTO user_coupon (
    user_id
    , item_id
    , coupon_code
    , cost_point
    , status
) VALUES (
    #{userId}
    , #{itemId}
    , #{couponCode}
    , #{costPoint}
    , 'AVAILABLE'
)

INSERT INTO point_history (
    user_id
    , mission_id
    , point
    , reason
) VALUES (
    #{userId}
    , NULL
    , #{point}
    , #{reason}
)
